import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/painting.dart';
import 'package:flutter_map/flutter_map.dart' as fm;

/// Deterministic 256×256 tile fixtures for tests and golden files — never
/// fetch live tiles in automated tests (plan §11). Two variants alternate
/// in a checkerboard so tile boundaries stay visible in screenshots.
final Uint8List kFakeTileLight = base64Decode(
  '',
);

final Uint8List kFakeTileDark = base64Decode(
  '',
);

/// Tile provider that serves the embedded fixtures — deterministic bytes,
/// no network. Alternate tiles in a checkerboard so pan/zoom seams show.
class FakeTileProvider extends fm.TileProvider {
  FakeTileProvider();

  @override
  ImageProvider getImage(
    fm.TileCoordinates coordinates,
    fm.TileLayer options,
  ) =>
      MemoryImage((coordinates.x + coordinates.y) % 2 == 0
          ? kFakeTileLight
          : kFakeTileDark);
}
